function maxScore(nums) {
  const n = nums.length;
  const dp = new Array(n).fill(0);

  for (let j = 1; j < n; j++) {
    for (let i = 0; i < j; i++) {
      dp[j] = Math.max(dp[j], dp[i] + (j - i) * nums[j]);
    }
  }
  return dp[n - 1];
}

