function maxScore(nums) {
  const n = nums.length;
  let best = 0;
  // Each mask chooses which middle indices the route lands on; index 0 and the last index are always on it.
  for (let mask = 0; mask < 1 << (n - 2); mask++) {
    let at = 0;
    let score = 0;
    for (let k = 1; k < n; k++) {
      if (k === n - 1 || (mask >> (k - 1)) & 1) {
        score += (k - at) * nums[k];
        at = k;
      }
    }
    best = Math.max(best, score);
  }
  return best;
}

