function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(900, 1000) : int(2, 10);
  const top = size === 'large' || rand() < 0.2 ? 100000 : int(1, 12);
  const shape = rand();
  const nums = Array.from({ length: n }, () => int(1, top));
  if (shape < 0.15) nums.sort((a, b) => a - b);
  else if (shape < 0.3) nums.sort((a, b) => b - a);
  else if (shape < 0.4) nums.fill(nums[0]);
  return [nums];
}
